struct bulk_Bdirect_traits {
static constexpr int B_M=BM,B_N=BN,B_K=256,T_M=1,T_N=2,T_K=1,BLOCK_SIZE=128;
static constexpr int MR=BM/16,NR=BN/32,STAGES=NB,B_AHEAD=BD,B_SETS=BD+1,N=NN,K=KK,M=MM,B_CACHE=BC;
static constexpr bool XCD_ORDER=XCD,SB_SLOTS=true,C_AGPR=false;
static constexpr int SCALE_COLS=KK/128,PANELS=KK/256,A_BYTES=BM*256;
static constexpr int SA_ROWS=BM,SA_BYTES=BLOCK_SIZE*4,SB_BYTES=BLOCK_SIZE*4;
static constexpr int OFF_SA=A_BYTES,OFF_SB=OFF_SA+SA_BYTES,STAGE_BYTES=OFF_SB+SB_BYTES;
static constexpr int A_COPIES=A_BYTES/(BLOCK_SIZE*16),B_ISSUES=NR*4,SCALE_ISSUES=2;
static constexpr int STAGE_ISSUES=A_COPIES+SCALE_ISSUES,PIPELINE_BYTES=NB*STAGE_BYTES,LDS_BYTES=PIPELINE_BYTES;
static constexpr int INITIAL_A=NB-1,INITIAL_B=BD,STEADY=PANELS-INITIAL_A;
static constexpr int wait_a(int t) {
int issued=INITIAL_B*B_ISSUES,ae=-1;
for(int i=0;i<INITIAL_A;++i) {issued+=STAGE_ISSUES;if(i==t)ae=issued;}
for(int s=0;s<t;++s) {
if(s+BD<PANELS)issued+=B_ISSUES;
if(s+NB-1<PANELS) {issued+=STAGE_ISSUES;if(s+NB-1==t)ae=issued;}
}
return issued-ae;
}
static constexpr int wait_b(int t) {
int issued=0,be=-1;
for(int i=0;i<INITIAL_B;++i) {issued+=B_ISSUES;if(i==t)be=issued;}
issued+=INITIAL_A*STAGE_ISSUES;
for(int s=0;s<=t;++s) {
if(s+BD<PANELS) {issued+=B_ISSUES;if(s+BD==t)be=issued;}
if(s+NB-1<PANELS)issued+=STAGE_ISSUES;
}
return issued-be;
}
static_assert(BM==64 && BN==32 && NB==4 && BD==2 && NN==7168);
static_assert((MM==48 || MM==64) && (KK==1024 || KK==3072));
static_assert(PANELS>=NB-1 && LDS_BYTES<=160*1024);
